<?php
require __DIR__.'/guard.php';if($user['role']!=='superadmin'){http_response_code(403);exit('Super administrator access required.');}$db=authDb();$error='';$message='';
if($_SERVER['REQUEST_METHOD']==='POST')try{checkCsrf();$action=$_POST['action']??'';$id=(int)($_POST['id']??0);if($action==='create'){$name=trim($_POST['name']??'');$username=trim($_POST['username']??'');$pass=$_POST['password']??'';$role=$_POST['role']??'staff';if(!$name||strlen($username)<3||strlen($pass)<10||!in_array($role,['staff','superadmin'],true))throw new Exception('Enter a name, username of at least 3 characters, and password of at least 10 characters.');$q=$db->prepare('INSERT INTO accounts(username,display_name,password_hash,role,active) VALUES(?,?,?,?,1)');$q->execute([$username,$name,password_hash($pass,PASSWORD_DEFAULT),$role]);$message='Account created.';}elseif($action==='activate'){$q=$db->prepare('UPDATE accounts SET active=1 WHERE id=?');$q->execute([$id]);$message='Account activated.';}elseif($action==='reset'){$pass=$_POST['password']??'';if(strlen($pass)<10)throw new Exception('Password must have at least 10 characters.');$q=$db->prepare('UPDATE accounts SET password_hash=?,reset_requested=0 WHERE id=?');$q->execute([password_hash($pass,PASSWORD_DEFAULT),$id]);$message='Password reset.';}}catch(Throwable $e){$error=$e instanceof PDOException?'That username is unavailable.':$e->getMessage();}
$accounts=$db->query('SELECT id,username,display_name,role,active,reset_requested FROM accounts ORDER BY id')->fetchAll(PDO::FETCH_ASSOC);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Accounts</title><link rel="stylesheet" href="../frontend/style.css"></head><body><main class="accountpage"><section class="panel"><div class="panelhead"><h1>Account management</h1><a class="button secondary" href="../index.php">← Back to inventory</a></div><?php if($error):?><div class="notice error"><?=esc($error)?></div><?php endif;?><?php if($message):?><div class="notice"><?=esc($message)?></div><?php endif;?><h2>Create account</h2><form method="post" class="formgrid"><input type="hidden" name="csrf" value="<?=esc(csrf())?>"><input type="hidden" name="action" value="create"><label>Name<input name="name" required></label><label>Username<input name="username" minlength="3" required></label><label>Temporary password<input type="password" name="password" minlength="10" required></label><label>Role<select name="role"><option value="staff">Staff</option><option value="superadmin">Super administrator</option></select></label><button class="button primary">Create account</button></form><h2>Accounts</h2><?php foreach($accounts as $account):?><div class="accountrow"><div><strong><?=esc($account['display_name'])?></strong><small><?=esc($account['username'])?> · <?=esc($account['role'])?> · <?=$account['active']?'Active':'Pending'?><?= $account['reset_requested']?' · Reset requested':'' ?></small></div><?php if(!$account['active']):?><form method="post"><input type="hidden" name="csrf" value="<?=esc(csrf())?>"><input type="hidden" name="action" value="activate"><input type="hidden" name="id" value="<?=$account['id']?>"><button class="button secondary">Activate</button></form><?php endif;?><form method="post" class="resetform"><input type="hidden" name="csrf" value="<?=esc(csrf())?>"><input type="hidden" name="action" value="reset"><input type="hidden" name="id" value="<?=$account['id']?>"><input name="password" type="password" minlength="10" placeholder="New password" required aria-label="New password"><button class="button secondary">Reset password</button></form></div><?php endforeach;?></section></main></body></html>
